name: bench-refresh

on:
  schedule:
    # Weekly, away from the top of the hour. A real-world benchmark is an hour
    # of runner time per pass; nightly would buy churn rather than signal.
    - cron: "41 4 * * 2"
  workflow_dispatch:
    inputs:
      force:
        description: Rerun the benchmark even when mbx's version has not changed
        required: false
        type: boolean
        default: false
      dry_run:
        description: Measure and upload the results, but propose nothing
        required: false
        type: boolean
        default: false
      source:
        description: Measure mbx built from this ref instead of the latest release (implies dry_run)
        required: false
        type: boolean
        default: false
      small_edit:
        description: Compare restored parent caches after hk's next small edit
        required: false
        type: boolean
        default: false
      small_edit_mbx_version:
        description: Released mbx version used by the small-edit comparison
        required: false
        type: string
        default: "1.11.1"
      small_edit_mbx_ref:
        description: Build this mr-boxington ref instead of installing a release
        required: false
        type: string
        default: ""
      small_edit_trials:
        description: JSON array of trial numbers (use [1] for a smoke test)
        required: false
        type: string
        default: "[1,2,3,4]"

permissions: {}

# Two refreshes would race the force-push to the shared `bench-refresh`
# branch. A manual dispatch supersedes an in-flight scheduled run.
concurrency:
  group: bench-refresh
  cancel-in-progress: true

env:
  CARGO_INCREMENTAL: "0"
  CARGO_TERM_COLOR: always
  # Keep rustup's proxies on PATH so RUSTUP_TOOLCHAIN selects the pinned
  # compiler the benchmark builds under.
  MISE_DISABLE_TOOLS: rust
  RUSTUP_TOOLCHAIN: 1.97.1

jobs:
  # Only benchmark when the mbx that produced the published numbers is older
  # than the latest release. A docs or chore push does not invalidate a timing,
  # and benchmarking an unreleased checkout would publish numbers users cannot
  # reproduce with the version they can install.
  check:
    name: Check version drift
    if: github.event_name != 'workflow_dispatch' || !inputs.small_edit
    runs-on: ubuntu-24.04
    timeout-minutes: 5
    permissions:
      contents: read
    outputs:
      drift: ${{ steps.drift.outputs.drift }}
      release: ${{ steps.drift.outputs.release }}
      bench: ${{ steps.drift.outputs.bench }}
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          persist-credentials: false
      - name: Compare latest release against published benchmark
        id: drift
        env:
          # A dry run is a request to measure, so it skips the drift check
          # the same way `force` does.
          FORCE_REFRESH: ${{ github.event_name == 'workflow_dispatch' && (inputs.force || inputs.dry_run || inputs.source) }}
          GH_TOKEN: ${{ github.token }}
        run: |
          RELEASE=$(gh release view --json tagName --jq '.tagName | ltrimstr("v")')
          # Absent until the first refresh lands, which is itself drift.
          BENCH=$(jq -r '.versions.mbx // empty' benchmarks/results.json 2>/dev/null || true)
          if [ -z "$RELEASE" ]; then
            echo "::error::Could not resolve the latest mbx release"
            exit 1
          fi
          echo "release=$RELEASE" >> "$GITHUB_OUTPUT"
          echo "bench=$BENCH" >> "$GITHUB_OUTPUT"
          if [ "$FORCE_REFRESH" = "true" ] || [ "$BENCH" != "$RELEASE" ]; then
            echo "drift=true" >> "$GITHUB_OUTPUT"
